        let result = match SourceBoundCellQ24TrainingStageV1::read_candidate_material(
            self.stage.as_ref(),
            &self.context.dataset,
        ) {
            Ok(material) => {
                let fresh_now = now()?;
                if fresh_now < started_at {
                    return Err(Error::Binding(                                          ));
                }
                wire::authenticate_receipt(
                    &self.context,
                    material.receipt().clone(),
                    material.attestation().clone(),
                    fresh_now,
                )?;
                match &request {
                    candidate_current::ReadRequest::Page(request) => {
                        candidate_wire::original_page(request, &material)?
                    }
                    candidate_current::ReadRequest::Current(request) => {
                        candidate_current::original_candidate_current_proof_v1(request, &material)?
                    }
                }
            }
            Err(OriginalCellQ24TrainingStageErrorV1::CandidateMaterial(
                OriginalCellQ24CandidateMaterialErrorV1::NoCandidate,
            )) => candidate_wire::MaterialResult::NoCandidate,
            Err(error) => match original_state(error) {
                wire::CommandResult::Missing => candidate_wire::MaterialResult::Missing,
                wire::CommandResult::Pending => candidate_wire::MaterialResult::Pending,
                wire::CommandResult::Busy => candidate_wire::MaterialResult::Busy,
                _ => candidate_wire::MaterialResult::Uncertain,
            },
        };
        match request {
            candidate_current::ReadRequest::Page(request) => {
                session.encode_response(request, result)
            }
            candidate_current::ReadRequest::Current(request) => {
                session.encode_current(request, result)
            }
        }

let request: candidate_current::ReadRequest =
            serde_json::from_slice(bytes).map_err(OriginalCellQ24TrainingCommandErrorV1::from)?;
        match &request {
            candidate_current::ReadRequest::Page(request) => {
                request.require_initial(&self.config.material, request_id)?;
                session.require_request(request)?;
            }
            candidate_current::ReadRequest::Current(request) => {
                request.require_initial(&self.config.material, request_id)?;
                session.require_current(request)?;
            }
        }
        if let Some(original) = self.ready()? {
            return Ok(
                OriginalCellQ24TrainingCommandOwnerV1::candidate_material_response(
                    original.as_ref(),
                    bytes,
                    request_id,
                    session,
                )?,
            );
        }


        Ok(match request {
            candidate_current::ReadRequest::Page(request) => session
                .encode_response(request, candidate_wire::MaterialResult::ReadbackRequired)?,
            candidate_current::ReadRequest::Current(request) => {
                session.encode_current(request, candidate_wire::MaterialResult::ReadbackRequired)?
            }
        })
